css:
/* Alumni Employee Request — approval-style single-record print.
   Kept to borders + light fills so it survives wkhtmltopdf and a mono printer. */

.aer {
	font-family: "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
	color: #1f272e;
	font-size: 11px;
	line-height: 1.45;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

.aer * {
	box-sizing: border-box;
}

/* ---------- masthead ---------- */

.aer-head {
	border: 1px solid #d5dbe1;
	border-top: 3px solid #1f4e79;
	border-radius: 3px;
	padding: 12px 14px;
	margin-bottom: 14px;
	background: #f7f9fb;
}

.aer-head-top {
	display: table;
	width: 100%;
}

.aer-head-left {
	display: table-cell;
	vertical-align: top;
}

.aer-head-right {
	display: table-cell;
	vertical-align: top;
	text-align: right;
	white-space: nowrap;
}

.aer-eyebrow {
	font-size: 9px;
	letter-spacing: 1.4px;
	text-transform: uppercase;
	color: #6b7a88;
	margin-bottom: 2px;
}

.aer-title {
	font-size: 17px;
	font-weight: 700;
	color: #1f4e79;
	line-height: 1.2;
}

.aer-subtitle {
	font-size: 11px;
	color: #55636f;
	margin-top: 2px;
}

.aer-id {
	font-size: 12px;
	font-weight: 700;
	color: #1f272e;
}

.aer-pill {
	display: inline-block;
	margin-top: 5px;
	padding: 3px 10px;
	border-radius: 11px;
	font-size: 9.5px;
	font-weight: 700;
	letter-spacing: 0.6px;
	text-transform: uppercase;
	border: 1px solid #b9c2cb;
	background: #eef1f4;
	color: #46525e;
}

.aer-pill-green {
	border-color: #9ed0ae;
	background: #e9f7ee;
	color: #1e6b39;
}

.aer-pill-amber {
	border-color: #e6c98a;
	background: #fdf5e4;
	color: #8a5f10;
}

.aer-pill-red {
	border-color: #e8aeae;
	background: #fdeeee;
	color: #9c2b2b;
}

.aer-pill-blue {
	border-color: #a8c4e0;
	background: #ecf3fa;
	color: #1f4e79;
}

/* ---------- sections ---------- */

.aer-section {
	margin-bottom: 13px;
	page-break-inside: avoid;
}

.aer-section-title {
	font-size: 10px;
	font-weight: 700;
	letter-spacing: 1.1px;
	text-transform: uppercase;
	color: #1f4e79;
	border-bottom: 1px solid #1f4e79;
	padding-bottom: 3px;
	margin-bottom: 7px;
}

/* label / value grid — two pairs per row */

.aer-grid {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}

.aer-grid td {
	padding: 4px 8px 4px 0;
	vertical-align: top;
	border-bottom: 1px solid #eef1f4;
}

.aer-label {
	width: 17%;
	color: #6b7a88;
	font-size: 9.5px;
	text-transform: uppercase;
	letter-spacing: 0.5px;
}

.aer-value {
	width: 33%;
	font-weight: 600;
	color: #1f272e;
	word-wrap: break-word;
}

/* ---------- prose ---------- */

.aer-prose {
	border: 1px solid #e3e8ec;
	border-left: 3px solid #b9c2cb;
	border-radius: 2px;
	background: #fbfcfd;
	padding: 8px 10px;
}

.aer-prose.aer-prose-red {
	border-left-color: #e8aeae;
	background: #fdf6f6;
}

.aer-pre {
	white-space: pre-wrap;
}

.aer-muted {
	color: #8a97a3;
	font-style: italic;
}

/* ---------- sign-off ---------- */

.aer-sign {
	width: 100%;
	border-collapse: separate;
	border-spacing: 10px 0;
	table-layout: fixed;
	margin-top: 18px;
	page-break-inside: avoid;
}

.aer-sign td {
	border: 1px solid #d5dbe1;
	border-radius: 3px;
	padding: 8px 10px 6px;
	vertical-align: top;
	height: 66px;
}

.aer-sign-role {
	font-size: 9px;
	letter-spacing: 0.8px;
	text-transform: uppercase;
	color: #6b7a88;
}

.aer-sign-name {
	font-size: 10.5px;
	font-weight: 600;
	margin-top: 2px;
}

.aer-sign-line {
	border-top: 1px dotted #9aa6b1;
	margin-top: 26px;
	padding-top: 3px;
	font-size: 8.5px;
	color: #8a97a3;
}

.aer-foot {
	margin-top: 12px;
	padding-top: 6px;
	border-top: 1px solid #e3e8ec;
	font-size: 8.5px;
	color: #8a97a3;
	display: table;
	width: 100%;
}

.aer-foot-left {
	display: table-cell;
	text-align: left;
}

.aer-foot-right {
	display: table-cell;
	text-align: right;
}

html:
{#- Alumni Employee Request — a single-record approval print.

    Same rule as the other Jinja print formats in this module: nothing empty
    prints — label/value pairs are filtered before layout, so a thin request
    (e.g. still Draft, no approval yet) prints short instead of a page of
    blank labels. Link values print as their title field, not their id. -#}

{%- macro t(dt, value) -%}
	{%- if value -%}
		{%- set title_field = frappe.get_meta(dt).get_title_field() -%}
		{%- if title_field == "name" -%}
			{{ value }}
		{%- else -%}
			{{ frappe.db.get_value(dt, value, title_field) or value }}
		{%- endif -%}
	{%- endif -%}
{%- endmacro -%}

{%- macro grid(pairs) -%}
	{%- set rows = [] -%}
	{%- for p in pairs if p[1] not in (None, "", 0) -%}
		{%- set _skip = rows.append(p) -%}
	{%- endfor -%}
	{%- if rows -%}
	<table class="aer-grid">
		{%- for chunk in rows | batch(2) -%}
		<tr>
			{%- for p in chunk -%}
			<td class="aer-label">{{ p[0] }}</td>
			<td class="aer-value">{{ p[1] }}</td>
			{%- endfor -%}
			{%- if chunk | length == 1 -%}
			<td class="aer-label"></td><td class="aer-value"></td>
			{%- endif -%}
		</tr>
		{%- endfor -%}
	</table>
	{%- endif -%}
{%- endmacro -%}

{%- set pill = {
	"Draft": "",
	"Pending Approval": "aer-pill-amber",
	"Approved": "aer-pill-green",
	"Rejected": "aer-pill-red",
	"Cancelled": "aer-pill-red"
}.get(doc.status, "") -%}

{%- set employee_name = doc.employee_name or t("Employee", doc.employee) -%}
{%- set company = t("Company", doc.company) -%}
{%- set approved_by = t("User", doc.approved_by) -%}

<div class="aer">

	<div class="aer-head">
		<div class="aer-head-top">
			<div class="aer-head-left">
				<div class="aer-eyebrow">{{ company or "" }}</div>
				<div class="aer-title">{{ employee_name or _("Alumni Employee Request") }}</div>
				<div class="aer-subtitle">{{ _("Alumni Employee Request") }}</div>
			</div>
			<div class="aer-head-right">
				<div class="aer-eyebrow">{{ _("Request No.") }}</div>
				<div class="aer-id">{{ doc.name }}</div>
				<div class="aer-pill {{ pill }}">{{ _(doc.status or "Draft") }}</div>
			</div>
		</div>
	</div>

	<div class="aer-section">
		<div class="aer-section-title">{{ _("Requestor Details") }}</div>
		{{ grid([
			(_("Employee"), employee_name),
			(_("Company"), company),
			(_("Email"), doc.email),
			(_("Mobile Number"), doc.mobile_number),
			(_("Date of Birth"), frappe.utils.formatdate(doc.date_of_birth) if doc.date_of_birth else ""),
			(_("Request Date"), frappe.utils.formatdate(doc.request_date) if doc.request_date else ""),
			(_("Created From"), doc.created_from),
		]) }}
	</div>

	{% if doc.remarks %}
	<div class="aer-section">
		<div class="aer-section-title">{{ _("Remarks") }}</div>
		<div class="aer-prose aer-pre">{{ doc.remarks }}</div>
	</div>
	{% endif %}

	<div class="aer-section">
		<div class="aer-section-title">{{ _("Approval") }}</div>
		{{ grid([
			(_("Status"), _(doc.status or "Draft")),
			(_("Approved By"), approved_by),
			(_("Approved On"), frappe.utils.format_datetime(doc.approved_on, "d MMM y, h:mm a") if doc.approved_on else ""),
		]) }}
		{% if doc.status == "Rejected" and doc.rejected_reason %}
		<div class="aer-prose aer-prose-red aer-pre" style="margin-top: 7px">{{ doc.rejected_reason }}</div>
		{% endif %}
	</div>

	{% if doc.current_alumni_status or doc.employee_exists %}
	<div class="aer-section">
		<div class="aer-section-title">{{ _("Verification") }}</div>
		{{ grid([
			(_("Employee Exists"), _("Yes") if doc.employee_exists else _("No")),
			(_("Current Alumni Status"), doc.current_alumni_status),
		]) }}
	</div>
	{% endif %}

	<table class="aer-sign">
		<tr>
			<td>
				<div class="aer-sign-role">{{ _("Requested By") }}</div>
				<div class="aer-sign-name">{{ employee_name or "&nbsp;" }}</div>
				<div class="aer-sign-line">{{ _("Signature & Date") }}</div>
			</td>
			<td>
				<div class="aer-sign-role">{{ _("Approved By") }}</div>
				<div class="aer-sign-name">{{ approved_by or "&nbsp;" }}</div>
				<div class="aer-sign-line">{{ _("Signature & Date") }}</div>
			</td>
		</tr>
	</table>

	<div class="aer-foot">
		<div class="aer-foot-left">{{ _("Alumni Employee Request") }} {{ doc.name }}</div>
		<div class="aer-foot-right">{{ _("Printed on") }} {{ frappe.utils.formatdate(frappe.utils.nowdate()) }}</div>
	</div>

</div>
